def intersection(interval1, interval2):
    start = max(interval1[0], interval2[0])
    end = min(interval1[1], interval2[1])
    if start > end:
        return "NO"

    length = end - start

    if length < 2:
        return "NO"
    d = 2
    while d * d <= length:
        if length % d == 0:
            return "NO"
        d += 1
    return "YES"

def can_arrange(arr):
    for i in range(1, len(arr)):
        if arr[i] <= arr[i - 1]:
            return i
    return -1

def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars",
               "Jupiter", "Saturn", "Uranus", "Neptune"]
    if planet1 not in planets or planet2 not in planets:
        return ()
    i, j = planets.index(planet1), planets.index(planet2)
    if i > j:
        i, j = j, i
    return tuple(planets[i + 1:j])

def select_words(s, n):
    vowels = set("aeiou")
    result = []
    for word in s.split():
        consonants = sum(c.lower() not in vowels for c in word)
        if consonants == n:
            result.append(word)
    return result

def x_or_y(n, x, y):
    if n < 2:
        return y
    if n == 2:
        return x
    d = 2
    while d * d <= n:
        if n % d == 0:
            return y
        d += 1
    return x

def pairs_sum_to_zero(l):
    seen = set()
    for x in l:
        if -x in seen:
            return True
        seen.add(x)
    return False

def words_in_sentence(sentence):
    def is_prime(n):
        if n < 2:
            return False
        d = 2
        while d * d <= n:
            if n % d == 0:
                return False
            d += 1
        return True

    return " ".join(word for word in sentence.split() if is_prime(len(word)))

